        od = abs(x - ox) + abs(y - oy)
        # Prefer (opponent_soon - self_soon) large; also prefer smaller self distance
        val = (od - sd) * 100 - sd
        if best is None or val > best[0] or (val == best[0] and (sd < best[1] or (sd == best[1] and (x, y) < best[2]))):
            best = (val, sd, (x, y))
    tx, ty = best[2]

